--- a/src/cache.js
+++ b/src/cache.js
@@ -3,6 +3,9 @@ class Cache {
   constructor() {
+    this.store = new Map();
+    this.timers = new Map();
   }
   set(key, value, ttl) {
+    this.store.set(key, value);
+    this.timers.set(key, setTimeout(() => this.store.delete(key), ttl));
   }
 }
